<script setup lang="ts">
import{computed,inject,watch}from'vue'
import type{SettingsClient}from'../bridge/clients/SettingsClient'
import type{MainWindowCloseBehavior,StartupPresentationMode}from'../contracts/settings'
import{useAppStore}from'../app/store';import{useSettingsStore}from'../app/settingsStore';import{useThemeStore,type ThemeMode}from'../app/themeStore';import{useToastStore}from'../app/toastStore'
import QPage from'../design-system/components/QPage.vue';import QButton from'../design-system/components/QButton.vue';import QIcon from'../design-system/components/QIcon.vue';import QSkeleton from'../design-system/components/QSkeleton.vue'
import brandMark from'../assets/QingToolbox.Mark.svg'
const client=inject<SettingsClient>('settingsClient')!;const app=useAppStore();const settings=useSettingsStore();const theme=useThemeStore();const toast=useToastStore();const themes:{mode:ThemeMode;label:string}[]=[{mode:'system',label:'Follow system'},{mode:'light',label:'Light'},{mode:'dark',label:'Dark'}]
const refreshed=computed(()=>settings.generatedAt?new Date(settings.generatedAt).toLocaleTimeString():null)
const productVersion=computed(()=>app.snapshot?.hostVersion||'0.2.0-alpha')
async function refresh(){settings.begin();try{settings.complete(await client.getSnapshot())}catch(error){settings.fail(error)}}
watch(()=>app.bridge,bridge=>{if(bridge==='Connected'&&settings.status==='idle')void refresh()},{immediate:true})
const yesNo=(value:boolean)=>value?'Yes':'No'
async function toggleLogs(){if(!settings.snapshot||settings.isUpdatingLogsVisibility)return;const result=await settings.updateLogsVisibility(client,!settings.snapshot.showLogsInSidebar);if(result==='success')toast.show('Logs navigation preference saved.','success');else if(result==='failure')toast.show('Logs navigation preference could not be saved.','error')}
const closeBehaviors:{value:MainWindowCloseBehavior;label:string;description:string}[]=[{value:'Ask',label:'Ask every time',description:'Ask what to do whenever the main window is closed.'},{value:'MinimizeToNotificationArea',label:'Minimize to notification area',description:'Hide the main window while QingToolbox continues running.'},{value:'ExitApplication',label:'Exit application',description:'Exit QingToolbox when the main window is closed.'}]
async function selectCloseBehavior(value:MainWindowCloseBehavior){if(!settings.snapshot||settings.isUpdatingCloseBehavior||settings.snapshot.mainWindowCloseBehavior===value)return;const result=await settings.updateCloseBehavior(client,value);if(result==='success')toast.show('Main window close behavior saved.','success');else if(result==='failure')toast.show('Main window close behavior could not be saved.','error')}
const startupPresentations:{value:StartupPresentationMode;label:string;description:string}[]=[{value:'MainWindow',label:'Show the main window',description:'Open QingToolbox with the main window visible.'},{value:'Minimized',label:'Start minimized',description:'Start QingToolbox minimized and ready in the background.'},{value:'FloatingBadge',label:'Show the floating badge',description:'Start with the compact floating badge instead of the main window.'}]
async function selectStartupPresentation(value:StartupPresentationMode){if(!settings.snapshot||settings.isUpdatingStartupPresentation||settings.snapshot.startupPresentationMode===value)return;const result=await settings.updateStartupPresentation(client,value);if(result==='success')toast.show('Startup presentation preference saved.','success');else if(result==='failure')toast.show('Startup presentation preference could not be saved.','error')}
</script>
<template><QPage class="settings-page"><section class="settings-panel"><header class="settings-header"><div><h1>Settings</h1><p>Review the current QingToolbox configuration.</p></div><QButton :disabled="app.bridge!=='Connected'||settings.status==='loading'" @click="refresh"><QIcon name="refresh"/> Refresh</QButton></header><div class="settings-readonly"><QIcon name="statusInfo"/> Some host settings can be changed from the Development Web workspace.</div><p v-if="settings.status==='ready'&&refreshed" class="settings-refreshed">Last refreshed {{refreshed}}</p>
<section class="settings-group appearance-group"><h2>Appearance</h2><p>This preview applies only to the Development Web workspace.</p><div class="theme-switch settings-theme"><button v-for="item in themes" :key="item.mode" :class="{active:theme.mode===item.mode}" @click="theme.set(item.mode)">{{item.label}}</button></div></section>
<section v-if="app.bridge!=='Connected'&&settings.status==='idle'" class="q-empty settings-state"><div class="q-empty-icon"><QIcon name="settings" :size="28"/></div><h3>Connecting to the host</h3><p>Settings will appear after the host bridge is ready.</p></section><section v-else-if="settings.status==='loading'" class="settings-skeleton" aria-label="Loading settings"><QSkeleton v-for="item in 4" :key="item"/></section><section v-else-if="settings.status==='error'" class="q-empty settings-state"><div class="q-empty-icon"><QIcon name="statusDanger" :size="28"/></div><h3>Settings are unavailable</h3><p>The current host configuration could not be read.</p><QButton @click="refresh"><QIcon name="refresh"/> Retry</QButton></section>
<template v-else-if="settings.snapshot"><section class="settings-group"><h2>Language</h2><p>The language currently selected by the host.</p><dl class="settings-values"><div><dt>Language</dt><dd>{{settings.snapshot.language.displayName}}</dd></div><div><dt>Language code</dt><dd>{{settings.snapshot.language.code}}</dd></div></dl></section><section class="settings-group"><h2>Logs</h2><p>Display the Session Logs entry in the workspace navigation.</p><div class="settings-switch-row"><div><strong>Show logs in sidebar</strong><small>Saved through the QingToolbox host.</small></div><button class="q-switch" type="button" role="switch" :aria-checked="settings.snapshot.showLogsInSidebar" :disabled="settings.isUpdatingLogsVisibility" @click="toggleLogs"><span/><em>{{settings.isUpdatingLogsVisibility?'Saving…':settings.snapshot.showLogsInSidebar?'On':'Off'}}</em></button></div><p v-if="settings.logsVisibilityError" class="settings-inline-error">The preference was not changed.</p></section><section class="settings-group"><h2>Window closing</h2><p>This applies the next time the main window is closed.</p><div class="close-behavior-group" role="radiogroup" aria-label="Main window close behavior" :aria-busy="settings.isUpdatingCloseBehavior"><button v-for="option in closeBehaviors" :key="option.value" type="button" role="radio" :aria-checked="settings.snapshot.mainWindowCloseBehavior===option.value" :disabled="settings.isUpdatingCloseBehavior" @click="selectCloseBehavior(option.value)"><span class="close-radio"/><span><strong>{{option.label}}</strong><small>{{option.description}}</small></span></button></div><p v-if="settings.isUpdatingCloseBehavior" class="settings-saving">Saving…</p><p v-else-if="settings.closeBehaviorError" class="settings-inline-error">The close behavior was not changed.</p><p v-else-if="settings.snapshot.closeBehaviorMessage" class="settings-host-message">{{settings.snapshot.closeBehaviorMessage}}</p></section><section class="settings-group startup-settings-group"><h2>Windows startup</h2><p>This takes effect the next time QingToolbox starts.</p><div class="close-behavior-group presentation-mode-group" role="radiogroup" aria-label="Startup presentation mode" :aria-busy="settings.isUpdatingStartupPresentation"><button v-for="option in startupPresentations" :key="option.value" type="button" role="radio" :aria-checked="settings.snapshot.startupPresentationMode===option.value" :disabled="settings.isUpdatingStartupPresentation" @click="selectStartupPresentation(option.value)"><span class="close-radio"/><span><strong>{{option.label}}</strong><small>{{option.description}}</small></span></button></div><p v-if="settings.isUpdatingStartupPresentation" class="settings-saving">Saving…</p><p v-else-if="settings.startupPresentationError" class="settings-inline-error">The startup presentation preference was not changed.</p><div class="startup-health-card"><h3>Startup health</h3><dl class="settings-values startup-health-values"><div><dt>Launch at login</dt><dd>{{yesNo(settings.snapshot.launchAtLogin)}}</dd></div><div><dt>Can configure startup</dt><dd>{{yesNo(settings.snapshot.canConfigureLaunchAtLogin)}}</dd></div><div><dt>Startup backend</dt><dd>{{settings.snapshot.startupBackend}}</dd></div><div><dt>Startup status</dt><dd>{{settings.snapshot.startupStatus}}</dd></div><div v-if="settings.snapshot.startupMessage"><dt>Message</dt><dd>{{settings.snapshot.startupMessage}}</dd></div></dl><div class="startup-health-actions"><QButton @click="refresh"><QIcon name="refresh"/> Refresh status</QButton></div></div></section></template><section class="settings-about" aria-label="About QingToolbox"><img :src="brandMark" alt="" aria-hidden="true"/><div><div class="settings-about-title"><strong>QingToolbox</strong><span>Preview</span></div><small>{{productVersion}}</small><p>Modular Windows toolbox.</p></div></section></section></QPage></template>
